select * from (select case when budget >= 3377000 then 'high' when budget >= 921000 then 'mid' else 'low' end as budget_bucket, avg(budget) as avg_budget, sum(case when dept_name = 'HR' then budget else 0 end) as hr_budget from departments group by case when budget >= 3377000 then 'high' when budget >= 921000 then 'mid' else 'low' end) as t where avg_budget < 2108000 order by hr_budget desc, budget_bucket limit 50;
